// Prevents additional console window on Windows in release
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use tauri::Manager;
mod auth;
mod storage;

#[tauri::command]
async fn scan_codebase(path: String) -> Result<String, String> {
    println!("Scanning repository at: {}", path);
    Ok(format!("Scan completed successfully for {}", path))
}

#[tauri::command]
fn get_system_metrics() -> String {
    "CORENOW Engine: 60 FPS | Delta-Cache: Active".into()
}

fn main() {
    tauri::Builder::default()
        .invoke_handler(tauri::generate_handler![scan_codebase, get_system_metrics])
        .run(tauri::generate_context!())
        .expect("Error while running Tauri Metropolis application");
}

