pub struct SessionManager {
    pub token: String,
    pub is_authenticated: bool,
    pub roles: Vec<String>,
}

impl SessionManager {
    pub fn new() -> Self {
        Self {
            token: String::new(),
            is_authenticated: false,
            roles: vec!["Analyst".to_string()],
        }
    }

    pub fn validate_token(&self, secret: &str) -> bool {
        if self.token.is_empty() || secret.is_empty() {
            return false;
        }
        self.token.starts_with(secret)
    }
}

