use std::collections::HashMap;

pub struct CacheStorage {
    cache_store: HashMap<String, String>,
}

impl CacheStorage {
    pub fn new() -> Self {
        Self { cache_store: HashMap::new() }
    }

    pub fn insert_entry(&mut self, sha: String, payload: String) {
        self.cache_store.insert(sha, payload);
    }

    pub fn retrieve_entry(&self, sha: &str) -> Option<&String> {
        self.cache_store.get(sha)
    }
}

