import * as THREE from 'three';

export function mountCityViewer(domElement: HTMLElement): void {
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x020804);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(200, 250, 300);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(domElement.clientWidth, domElement.clientHeight);
    domElement.appendChild(renderer.domElement);

    const light = new THREE.DirectionalLight(0xd9ff3d, 1.2);
    light.position.set(100, 200, 100);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0x223322, 0.8));

    function animate() {
        requestAnimationFrame(animate);
        renderer.render(scene, camera);
    }
    animate();
}

