export async function invokeCommand(command: string, args?: Record<string, unknown>): Promise<any> {
    if ((window as any).__TAURI_INTERNALS__) {
        return (window as any).__TAURI_INTERNALS__.invoke(command, args);
    }
    return `[Mock Tauri IPC] Executed ${command}`;
}

