import hashlib
from typing import Dict, Any

def compute_sha256(content: str) -> str:
    return hashlib.sha256(content.encode('utf-8')).hexdigest()

def classify_intent(path: str) -> str:
    if 'auth' in path:
        return 'Auth'
    elif 'api' in path or 'route' in path:
        return 'API'
    elif 'store' in path or 'db' in path:
        return 'Data'
    elif 'component' in path or 'view' in path:
        return 'UI'
    return 'Core'

